-- GENERATED by scratch-tools/gen_notify_migration.py: business RPCs with e-mail notifications.
-- Each notify_* call runs inside the business transaction (outbox pattern, see 20261026000200).

create or replace function private.create_investment_request(payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  -- Reservation policy (review F-03): open = awaiting_payment | under_review.
  c_max_open_requests constant integer := 3;
  c_max_open_shares constant integer := 8;
  c_ttl constant interval := interval '30 minutes';
  v_uid uuid := private.require_user();
  p jsonb := coalesce(payload, '{}'::jsonb);
  v_tree_id text;
  v_share_count integer;
  v_includes_land boolean := false;
  v_key text;
  v_request_id text;
  v_existing public.investment_requests;
  v_tree private.trees;
  v_has_land boolean;
  v_open_count integer;
  v_open_shares integer;
  v_available integer;
  v_amount bigint;
  v_expires timestamptz;
begin
  perform private.require_verified_email(v_uid, 'Verify your email before requesting an investment.');

  v_tree_id := private.req_id(p, 'treeId', '^[A-Za-z0-9_-]{1,80}$');
  -- Nested checks: never cast before the JSON type is known (NULL-safe, no cast errors).
  if jsonb_typeof(p -> 'shareCount') is distinct from 'number' then
    perform private.fail('invalid-argument', 'Share count must be between 1 and 1000.');
  end if;
  if (p ->> 'shareCount')::numeric <> trunc((p ->> 'shareCount')::numeric)
     or (p ->> 'shareCount')::numeric not between 1 and 1000 then
    perform private.fail('invalid-argument', 'Share count must be between 1 and 1000.');
  end if;
  v_share_count := (p ->> 'shareCount')::integer;
  if p ? 'includesLand' then
    if jsonb_typeof(p -> 'includesLand') <> 'boolean' then
      perform private.fail('invalid-argument', 'includesLand must be a boolean.');
    end if;
    v_includes_land := (p ->> 'includesLand')::boolean;
  end if;
  if jsonb_typeof(p -> 'idempotencyKey') is distinct from 'string'
     or char_length(p ->> 'idempotencyKey') not between 16 and 120 then
    perform private.fail('invalid-argument', 'A valid idempotency key is required.');
  end if;
  v_key := p ->> 'idempotencyKey';

  -- Deterministic id: same user + key always maps to one request (safe client retries).
  v_request_id := encode(sha256(convert_to(v_uid::text || ':' || v_key, 'UTF8')), 'hex');

  -- Serialize all reservations of this user so the quota check cannot be raced.
  perform pg_advisory_xact_lock(hashtextextended('faseela:reserve:' || v_uid::text, 0));

  select * into v_existing from public.investment_requests where id = v_request_id;
  if found then
    if v_existing.user_id <> v_uid then
      perform private.fail('permission-denied', 'Request key is already in use.');
    end if;
    return jsonb_build_object('requestId', v_existing.id, 'status', v_existing.status,
      'amountMinor', v_existing.amount_minor, 'expiresAt', private.epoch_ms(v_existing.expires_at));
  end if;

  select pt.has_land_option into v_has_land
    from public.trees_public pt
   where pt.tree_id = v_tree_id and pt.status = 'listed';
  if not found then
    perform private.fail('not-found', 'This tree is not currently available.');
  end if;
  -- Row lock on the inventory serializes concurrent reservations of the same tree.
  select t.* into v_tree from private.trees t where t.tree_id = v_tree_id for update;
  if not found then
    perform private.fail('not-found', 'This tree is not currently available.');
  end if;

  if exists (select 1 from public.investment_requests
              where user_id = v_uid and status in ('awaiting_payment', 'under_review') and tree_id = v_tree_id) then
    perform private.fail('already-exists', 'You already have an open request for this tree. Complete or cancel it first.');
  end if;
  select count(*), coalesce(sum(share_count), 0) into v_open_count, v_open_shares
    from public.investment_requests
   where user_id = v_uid and status in ('awaiting_payment', 'under_review');
  if v_open_count >= c_max_open_requests then
    perform private.fail('resource-exhausted', 'Too many open investment requests. Complete or cancel one first.');
  end if;
  if v_open_shares + v_share_count > c_max_open_shares then
    perform private.fail('resource-exhausted', 'This request exceeds the number of shares you can reserve at once.');
  end if;

  v_available := v_tree.total_shares - v_tree.sold_shares - v_tree.reserved_shares;
  if v_share_count > v_available then
    perform private.fail('failed-precondition', 'Not enough shares are available.');
  end if;
  if v_share_count > v_tree.total_shares then
    perform private.fail('invalid-argument', 'Requested shares exceed the tree total.');
  end if;
  if v_includes_land and (not v_has_land or v_share_count <> v_tree.total_shares) then
    perform private.fail('failed-precondition', 'Land can currently be reserved only with a complete tree.');
  end if;

  v_amount := v_share_count::bigint * v_tree.price_per_share_minor
              + case when v_includes_land then v_tree.land_price_minor else 0 end;
  v_expires := now() + c_ttl;

  update private.trees set reserved_shares = reserved_shares + v_share_count, updated_at = now()
   where tree_id = v_tree_id;
  perform private.sync_available(v_tree_id);

  insert into public.investment_requests (id, user_id, tree_id, share_count, includes_land, amount_minor,
                                          currency, status, expires_at)
  values (v_request_id, v_uid, v_tree_id, v_share_count, v_includes_land, v_amount,
          v_tree.currency, 'awaiting_payment', v_expires);
  insert into public.transactions (id, request_id, user_id, type, amount_minor, currency, status)
  values (v_request_id, v_request_id, v_uid, 'share_purchase', v_amount, v_tree.currency, 'pending');

  perform private.notify_user(v_uid, 'reservation_created', jsonb_build_object(
    'requestId', v_request_id, 'treeId', v_tree_id, 'shareCount', v_share_count, 'includesLand', v_includes_land,
    'amountMinor', v_amount, 'currency', v_tree.currency, 'expiresAt', private.epoch_ms(v_expires)));
  return jsonb_build_object('requestId', v_request_id, 'status', 'awaiting_payment',
    'amountMinor', v_amount, 'expiresAt', private.epoch_ms(v_expires));
end;
$$;

create or replace function private.submit_investment_payment_proof(payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  p jsonb := coalesce(payload, '{}'::jsonb);
  v_request_id text := private.req_id(p, 'requestId', '^[a-f0-9]{64}$');
  v_path text := private.req_id(p, 'storagePath', '^[A-Za-z0-9._/-]{1,240}$');
  v_req public.investment_requests;
begin
  -- Object name inside bucket `payment-proofs`: {uid}/{requestId}/{file}
  if v_path not like v_uid::text || '/' || v_request_id || '/%'
     or position('..' in v_path) > 0
     or v_path !~ '^[0-9a-f-]{36}/[a-f0-9]{64}/[A-Za-z0-9._-]{1,120}$' then
    perform private.fail('invalid-argument', 'Payment proof reference is invalid.');
  end if;
  if not exists (
    select 1 from storage.objects o
     where o.bucket_id = 'payment-proofs'
       and o.name = v_path
       and o.owner_id = v_uid::text
       and o.metadata ->> 'mimetype' in ('image/jpeg', 'image/png', 'application/pdf')
       and coalesce(o.is_delete_marker, false) = false
  ) then
    perform private.fail('failed-precondition', 'Upload a supported payment receipt first.');
  end if;

  select * into v_req from public.investment_requests where id = v_request_id and user_id = v_uid for update;
  if not found then
    perform private.fail('not-found', 'Investment request was not found.');
  end if;
  if v_req.status <> 'awaiting_payment' or v_req.expires_at <= now() then
    perform private.fail('failed-precondition', 'This payment request has expired or was already submitted.');
  end if;

  update public.investment_requests
     set status = 'under_review', payment_proof_path = v_path, proof_submitted_at = now(), updated_at = now()
   where id = v_request_id;
  update public.transactions set status = 'under_review', updated_at = now() where id = v_request_id;
  perform private.notify_user(v_uid, 'proof_received', jsonb_build_object('requestId', v_request_id, 'treeId', v_req.tree_id, 'amountMinor', v_req.amount_minor, 'currency', v_req.currency));
  perform private.notify_role('finance_admin', 'review_needed', jsonb_build_object('queue', 'payments', 'requestId', v_request_id, 'amountMinor', v_req.amount_minor, 'currency', v_req.currency));
  return jsonb_build_object('requestId', v_request_id, 'status', 'under_review');
end;
$$;

create or replace function private.review_investment_request(payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_role(array['finance_admin']);
  p jsonb := coalesce(payload, '{}'::jsonb);
  v_request_id text := private.req_id(p, 'requestId', '^[a-f0-9]{64}$');
  v_decision text := private.req_id(p, 'decision', '^(approve|reject)$');
  v_note text := private.parse_note(p);
  v_status text := case when v_decision = 'approve' then 'approved' else 'rejected' end;
  v_req public.investment_requests;
  v_reserved integer;
begin
  select * into v_req from public.investment_requests where id = v_request_id for update;
  if not found then
    perform private.fail('not-found', 'Investment request was not found.');
  end if;
  perform private.assert_not_self_review(v_uid, v_req.user_id);
  if v_req.status <> 'under_review' then
    perform private.fail('failed-precondition', 'Only reviewed payment requests can be decided.');
  end if;
  if exists (select 1 from public.shares where id = v_request_id) then
    perform private.fail('already-exists', 'A share record already exists for this request.');
  end if;

  select reserved_shares into v_reserved from private.trees where tree_id = v_req.tree_id for update;
  if not found or v_reserved < v_req.share_count then
    perform private.fail('failed-precondition', 'Reserved inventory is inconsistent.');
  end if;

  update private.trees
     set reserved_shares = reserved_shares - v_req.share_count,
         sold_shares = sold_shares + case when v_decision = 'approve' then v_req.share_count else 0 end,
         updated_at = now()
   where tree_id = v_req.tree_id;
  perform private.sync_available(v_req.tree_id);

  update public.investment_requests
     set status = v_status, reviewed_by_uid = v_uid, review_note = v_note, reviewed_at = now(), updated_at = now()
   where id = v_request_id;
  update public.transactions
     set status = case when v_decision = 'approve' then 'settled' else 'rejected' end,
         reviewed_by_uid = v_uid, reviewed_at = now(), updated_at = now()
   where id = v_request_id;

  if v_decision = 'approve' then
    insert into public.shares (id, request_id, user_id, tree_id, share_count, includes_land,
                               purchase_price_minor, currency, status)
    values (v_request_id, v_request_id, v_req.user_id, v_req.tree_id, v_req.share_count, v_req.includes_land,
            v_req.amount_minor, v_req.currency, 'active');
  end if;

  perform private.audit(v_uid, 'investment_request.' || v_status, 'investment_requests/' || v_request_id,
    jsonb_build_object('userId', v_req.user_id, 'treeId', v_req.tree_id, 'shareCount', v_req.share_count,
                       'amountMinor', v_req.amount_minor, 'note', v_note));
  perform private.notify_user(v_req.user_id, 'payment_' || v_status, jsonb_build_object('requestId', v_request_id, 'treeId', v_req.tree_id, 'shareCount', v_req.share_count, 'amountMinor', v_req.amount_minor, 'currency', v_req.currency, 'note', v_note));
  return jsonb_build_object('requestId', v_request_id, 'status', v_status);
end;
$$;

create or replace function private.expire_investment_requests()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_req record;
  v_count integer := 0;
begin
  for v_req in
    select id, tree_id, share_count, user_id, amount_minor, currency from public.investment_requests
     where status = 'awaiting_payment' and expires_at <= now()
     order by expires_at
     limit 100
     for update skip locked
  loop
    perform 1 from private.trees where tree_id = v_req.tree_id for update;
    perform private.release_reservation(v_req.tree_id, v_req.share_count);
    update public.investment_requests set status = 'expired', updated_at = now() where id = v_req.id;
    update public.transactions set status = 'expired', updated_at = now() where id = v_req.id;
    perform private.notify_user(v_req.user_id, 'reservation_expired', jsonb_build_object('requestId', v_req.id, 'treeId', v_req.tree_id, 'shareCount', v_req.share_count, 'amountMinor', v_req.amount_minor, 'currency', v_req.currency));
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;

create or replace function private.flag_overdue_reviews()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_req record;
  v_count integer := 0;
begin
  for v_req in
    update public.investment_requests
       set sla_breached = true, sla_breached_at = now()
     where status = 'under_review'
       and sla_breached = false
       and proof_submitted_at <= now() - interval '72 hours'
    returning id, tree_id, share_count
  loop
    perform private.audit(null, 'investment_request.review_sla_breached', 'investment_requests/' || v_req.id,
      jsonb_build_object('treeId', v_req.tree_id, 'shareCount', v_req.share_count));
    v_count := v_count + 1;
  end loop;
  if v_count > 0 then
    perform private.notify_role('admin', 'review_overdue', jsonb_build_object('count', v_count));
  end if;
  return v_count;
end;
$$;

create or replace function private.review_role_application(payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_role('{}'::text[]);
  p jsonb := coalesce(payload, '{}'::jsonb);
  v_target uuid := private.req_uuid(p, 'userId');
  v_decision text := private.req_id(p, 'decision', '^(approve|reject)$');
  v_note text := private.parse_note(p);
  v_status text := case when v_decision = 'approve' then 'approved' else 'rejected' end;
  v_app public.role_applications;
begin
  perform private.assert_not_self_review(v_uid, v_target);
  select * into v_app from public.role_applications where user_id = v_target for update;
  if not found or v_app.status <> 'pending' then
    perform private.fail('failed-precondition', 'Role application is not pending.');
  end if;

  update public.role_applications
     set status = v_status, reviewed_by_uid = v_uid, review_note = v_note, reviewed_at = now()
   where user_id = v_target;

  -- Role grant and decision commit atomically (no separate claims step to roll back).
  if v_decision = 'approve' then
    insert into private.user_roles (user_id, role, granted_by, granted_at)
    values (v_target, v_app.requested_role, v_uid, now())
    on conflict (user_id) do update
       set role = excluded.role, granted_by = excluded.granted_by, granted_at = excluded.granted_at;
  end if;

  perform private.audit(v_uid, 'role_application.' || v_status, 'role_applications/' || v_target,
    jsonb_build_object('userId', v_target, 'requestedRole', v_app.requested_role, 'note', v_note));
  perform private.notify_user(v_target, 'role_' || v_status, jsonb_build_object('requestedRole', v_app.requested_role, 'note', v_note));
  return jsonb_build_object('userId', v_target, 'status', v_status);
end;
$$;

create or replace function private.submit_farmer_update(payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_role(array['farmer']);
  p jsonb := coalesce(payload, '{}'::jsonb);
  v_tree_id text := private.req_id(p, 'treeId', '^[A-Za-z0-9_-]{1,80}$');
  v_event text := private.req_id(p, 'eventType', '^(watering|pruning|fertilizing|pest_control|harvest|other)$');
  v_notes text;
  v_media text[] := '{}';
  v_item jsonb;
  v_lat double precision;
  v_lng double precision;
  v_id uuid;
begin
  if jsonb_typeof(p -> 'notes') is distinct from 'string' or char_length(p ->> 'notes') > 1200 then
    perform private.fail('invalid-argument', 'Farmer update data is invalid.');
  end if;
  v_notes := p ->> 'notes';
  if jsonb_typeof(p -> 'mediaPaths') is distinct from 'array' or jsonb_array_length(p -> 'mediaPaths') > 5 then
    perform private.fail('invalid-argument', 'Farmer update data is invalid.');
  end if;
  for v_item in select value from jsonb_array_elements(p -> 'mediaPaths') loop
    -- Object names inside bucket `field-media`: {uid}/{treeId}/{file}
    if jsonb_typeof(v_item) <> 'string' or char_length(v_item #>> '{}') > 300
       or (v_item #>> '{}') not like v_uid::text || '/' || v_tree_id || '/%'
       or position('..' in (v_item #>> '{}')) > 0 then
      perform private.fail('invalid-argument', 'Media must be uploaded to your own field-media folder for this tree.');
    end if;
    v_media := v_media || (v_item #>> '{}');
  end loop;
  if p ? 'gpsLat' and jsonb_typeof(p -> 'gpsLat') <> 'null' then
    v_lat := private.req_number(p, 'gpsLat');
    if v_lat not between -90 and 90 then perform private.fail('invalid-argument', 'GPS coordinates are invalid.'); end if;
  end if;
  if p ? 'gpsLng' and jsonb_typeof(p -> 'gpsLng') <> 'null' then
    v_lng := private.req_number(p, 'gpsLng');
    if v_lng not between -180 and 180 then perform private.fail('invalid-argument', 'GPS coordinates are invalid.'); end if;
  end if;

  if not private.farmer_has_tree(v_uid, v_tree_id) then
    perform private.fail('permission-denied', 'Tree is not assigned to this farmer.');
  end if;

  insert into public.farmer_updates (farmer_uid, tree_id, event_type, notes, media_paths, gps_lat, gps_lng, status)
  values (v_uid, v_tree_id, v_event, v_notes, v_media, v_lat, v_lng, 'pending_review')
  returning id into v_id;
  perform private.notify_role('quality_auditor', 'review_needed', jsonb_build_object('queue', 'farmer_updates', 'treeId', v_tree_id));
  return jsonb_build_object('updateId', v_id, 'status', 'pending_review');
end;
$$;

create or replace function private.review_farmer_update(payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_role(array['quality_auditor']);
  p jsonb := coalesce(payload, '{}'::jsonb);
  v_id uuid := private.req_uuid(p, 'updateId');
  v_decision text := private.req_id(p, 'decision', '^(publish|reject)$');
  v_note text := private.parse_note(p);
  v_status text := case when v_decision = 'publish' then 'published' else 'rejected' end;
  v_upd public.farmer_updates;
begin
  select * into v_upd from public.farmer_updates where id = v_id for update;
  if not found or v_upd.status <> 'pending_review' then
    perform private.fail('failed-precondition', 'Farmer update is not pending review.');
  end if;
  perform private.assert_not_self_review(v_uid, v_upd.farmer_uid);

  update public.farmer_updates
     set status = v_status, review_note = v_note, reviewed_by_uid = v_uid, reviewed_at = now()
   where id = v_id;
  if v_decision = 'publish' then
    -- Media stays private in Storage; only the count is published.
    insert into public.tree_events_public (tree_id, event_type, notes, media_count, event_date, status)
    values (v_upd.tree_id, v_upd.event_type, v_upd.notes, cardinality(v_upd.media_paths), v_upd.created_at, 'published');
  end if;
  perform private.audit(v_uid, 'farmer_update.' || v_status, 'farmer_updates/' || v_id,
    jsonb_build_object('treeId', v_upd.tree_id, 'farmerUid', v_upd.farmer_uid, 'note', v_note));
  perform private.notify_user(v_upd.farmer_uid, 'farmer_update_' || v_status, jsonb_build_object('treeId', v_upd.tree_id, 'eventType', v_upd.event_type, 'note', v_note));
  return jsonb_build_object('updateId', v_id, 'status', v_status);
end;
$$;

create or replace function private.submit_pressing_batch(payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_role(array['mill_operator']);
  p jsonb := coalesce(payload, '{}'::jsonb);
  v_tree_id text := private.req_id(p, 'treeId', '^[A-Za-z0-9_-]{1,80}$');
  v_mill_id text := private.req_id(p, 'millId', '^[A-Za-z0-9_-]{1,80}$');
  v_weight numeric := private.req_number(p, 'olivesWeightKg');
  v_oil numeric := private.req_number(p, 'oilYieldLiters');
  v_temp numeric := private.req_number(p, 'temperatureCelsius');
  v_acid numeric := private.req_number(p, 'acidityPct');
  v_perox numeric := private.req_number(p, 'peroxideValue');
  v_id uuid;
begin
  if v_weight <= 0 or v_oil < 0 or v_temp not between 0 and 40
     or v_acid not between 0 and 100 or v_perox not between 0 and 100 then
    perform private.fail('invalid-argument', 'Pressing batch values are outside allowed bounds.');
  end if;
  if not private.operator_has_mill(v_uid, v_mill_id) then
    perform private.fail('permission-denied', 'Mill is not assigned to this operator.');
  end if;
  if not exists (select 1 from public.trees_public where tree_id = v_tree_id and status = 'listed') then
    perform private.fail('not-found', 'This tree is not available for pressing records.');
  end if;

  insert into public.pressing_batches (submitted_by_uid, tree_id, mill_id, olives_weight_kg, oil_yield_liters,
                                       temperature_celsius, acidity_pct, peroxide_value, season_year, status)
  values (v_uid, v_tree_id, v_mill_id, v_weight, v_oil, v_temp, v_acid, v_perox,
          extract(year from (now() at time zone 'utc'))::integer, 'pending_review')
  returning id into v_id;
  perform private.notify_role('quality_auditor', 'review_needed', jsonb_build_object('queue', 'pressing_batches', 'treeId', v_tree_id, 'millId', v_mill_id));
  return jsonb_build_object('batchId', v_id, 'status', 'pending_review');
end;
$$;

create or replace function private.certify_pressing_batch(payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_role(array['quality_auditor']);
  p jsonb := coalesce(payload, '{}'::jsonb);
  v_id uuid := private.req_uuid(p, 'batchId');
  v_decision text := coalesce(private.opt_text(p, 'decision', 10), 'certify');
  v_serial text := private.opt_text(p, 'certificateSerial', 120);
  v_note text := private.parse_note(p);
  v_status text;
  v_batch public.pressing_batches;
begin
  if v_decision not in ('certify', 'reject') then
    perform private.fail('invalid-argument', 'Batch review request is invalid.');
  end if;
  if v_decision = 'certify' and (v_serial is null or v_serial !~ '^[A-Za-z0-9_-]{1,120}$') then
    perform private.fail('invalid-argument', 'A certificate serial is required to certify a batch.');
  end if;
  if v_decision = 'reject' then
    v_serial := null;
  end if;
  v_status := case when v_decision = 'certify' then 'certified' else 'rejected' end;

  select * into v_batch from public.pressing_batches where id = v_id for update;
  if not found or v_batch.status <> 'pending_review' then
    perform private.fail('failed-precondition', 'Pressing batch is not pending review.');
  end if;
  perform private.assert_not_self_review(v_uid, v_batch.submitted_by_uid);

  update public.pressing_batches
     set status = v_status, certificate_serial = v_serial, review_note = v_note,
         certified_by_uid = v_uid, certified_at = now()
   where id = v_id;
  if v_decision = 'certify' then
    insert into public.tree_events_public (tree_id, event_type, batch_id, certificate_serial, oil_yield_liters,
                                           acidity_pct, peroxide_value, status)
    values (v_batch.tree_id, 'pressing_certified', v_id, v_serial, v_batch.oil_yield_liters,
            v_batch.acidity_pct, v_batch.peroxide_value, 'published');
  end if;
  perform private.audit(v_uid, 'pressing_batch.' || v_status, 'pressing_batches/' || v_id,
    jsonb_build_object('treeId', v_batch.tree_id, 'millId', v_batch.mill_id, 'certificateSerial', v_serial, 'note', v_note));
  perform private.notify_user(v_batch.submitted_by_uid, 'batch_' || v_status, jsonb_build_object('batchId', v_id, 'treeId', v_batch.tree_id, 'certificateSerial', v_serial, 'note', v_note));
  return jsonb_build_object('batchId', v_id, 'status', v_status);
end;
$$;

create or replace function private.submit_role_application(payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  p jsonb := coalesce(payload, '{}'::jsonb);
  v_role text := private.opt_text(p, 'requestedRole', 20);
  v_region text := private.opt_text(p, 'region', 120);
  v_org text := coalesce(btrim(private.opt_text(p, 'organizationName', 160)), '');
  v_msg text := coalesce(btrim(private.opt_text(p, 'message', 1000)), '');
  v_existing public.role_applications;
begin
  perform private.require_verified_email(v_uid, 'Verify your email before requesting an operator role.');
  if v_role is null or v_role not in ('farmer', 'mill_operator')
     or v_region is null or char_length(btrim(v_region)) < 2 then
    perform private.fail('invalid-argument', 'Role application data is invalid.');
  end if;

  select * into v_existing from public.role_applications where user_id = v_uid for update;
  if found then
    if v_existing.status = 'pending' then
      return jsonb_build_object('status', 'pending', 'requestedRole', v_existing.requested_role);
    end if;
    if v_existing.status = 'approved' and v_existing.requested_role = v_role then
      return jsonb_build_object('status', 'approved', 'requestedRole', v_existing.requested_role);
    end if;
  end if;

  insert into public.role_applications (user_id, requested_role, region, organization_name, message, status,
                                        submitted_at, reviewed_at, reviewed_by_uid, review_note)
  values (v_uid, v_role, btrim(v_region), v_org, v_msg, 'pending', now(), null, null, '')
  on conflict (user_id) do update
     set requested_role = excluded.requested_role,
         region = excluded.region,
         organization_name = excluded.organization_name,
         message = excluded.message,
         status = 'pending',
         submitted_at = now(),
         reviewed_at = null,
         reviewed_by_uid = null,
         review_note = '';
  perform private.notify_role('admin', 'review_needed', jsonb_build_object('queue', 'role_applications', 'requestedRole', v_role));
  return jsonb_build_object('status', 'pending', 'requestedRole', v_role);
end;
$$;
